# Let's inspect the fiber tree / form container to see how onChange is handled
print(js("""
(() => {
    const el = document.getElementById('answer-input');
    const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber'));
    let fiber = el[fiberKey];
    const hierarchy = [];
    while (fiber) {
        if (fiber.memoizedProps) {
            hierarchy.push({
                type: typeof fiber.type === 'string' ? fiber.type : (fiber.type?.name || 'function'),
                props: Object.keys(fiber.memoizedProps),
                onChange: fiber.memoizedProps.onChange ? fiber.memoizedProps.onChange.toString().slice(0, 100) : null
            });
        }
        fiber = fiber.return;
    }
    return hierarchy.slice(0, 8);
})()
"""))

